function C({registerIndicator:v,sourceValues:V,nulls:w}){v({id:"oa-stbands",name:"Super Trend Bands (STBANDS)",category:"Channels",placement:"onchart",inputs:[{key:"period",type:"number",label:"ATR Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"},{key:"multiplier",type:"number",label:"ATR Multiplier",default:3,min:.001,max:100,step:.1}],plots:[{key:"upper",type:"line",title:"Upper Band",style:{color:"#ffeb3b",lineWidth:2}},{key:"lower",type:"line",title:"Lower Band",style:{color:"#ffeb3b",lineWidth:2}}],fills:[{between:["upper","lower"],colorUp:"#2962ff",colorDown:"#2962ff",opacity:.1}],calc(l,c){const y=Math.max(1,Math.floor(Number(c.period)||10)),M=Math.max(.001,Number(c.multiplier)||3),p=V(l,c.source??"close"),u=l.length,x=new Array(u).fill(NaN),F=new Array(u).fill(NaN),S=new Array(y).fill(NaN);let m=0,o=0,i=0,t=NaN,r=NaN;for(let e=0;e<u;e++){const A=Number(l[e].high),k=Number(l[e].low),b=Number.isFinite(A)?A:0,f=Number.isFinite(k)?k:0,g=Number.isFinite(p[e])?p[e]:0,B=e>0?p[e-1]:NaN,n=Number.isFinite(B)?B:g,N=Math.max(b-f,Math.max(Math.abs(b-n),Math.abs(f-n))),L=S[o];Number.isFinite(L)&&(m-=L,i-=1),m+=N,i+=1,S[o]=N,o=(o+1)%y;const T=i>0?m/i:N,U=(b+f)/2,a=U+M*T,s=U-M*T;if(e===0)t=a,r=s;else{const d=Number.isFinite(t)?t:a,h=Number.isFinite(r)?r:s;t=a<d||n>d?a:d,r=s>h||n<h?s:h}x[e]=t,F[e]=r}return{upper:w(x),lower:w(F)}}})}export{C as default};
